// SLA policies' first_response_minutes, in seconds, over the same cohort as the first-response
// times. n is 0 (and the median 0) when none of them has a target.
func (q *Queries) ReportFirstResponseTarget(ctx context.Context, arg ReportFirstResponseTargetParams) (ReportFirstResponseTargetRow, error) {
	row := q.db.QueryRow(ctx, reportFirstResponseTarget,
		arg.RangeFrom,
		arg.RangeTo,
		arg.MailboxIds,
		arg.TeamID,
		arg.AgentID,
		arg.LabelID,
	)
	var i ReportFirstResponseTargetRow
	err := row.Scan(&i.N, &i.MedianSeconds)
	return i, err
}

const reportLifecycle = `-- name: ReportLifecycle :many
SELECT (c.created_at AT TIME ZONE $1::text)::date AS day,
       count(*) FILTER (WHERE c.status = 'spam')::bigint AS spam,
       count(*) FILTER (WHERE c.status = 'open' AND c.first_responded_at IS NOT NULL)::bigint AS answered_open,
       count(*) FILTER (WHERE c.status = 'waiting' AND c.first_responded_at IS NOT NULL)::bigint AS answered_waiting,
       count(*) FILTER (WHERE c.status = 'closed' AND c.first_responded_at IS NOT NULL)::bigint AS answered_closed,
       count(*) FILTER (WHERE c.status = 'open' AND c.first_responded_at IS NULL)::bigint AS unanswered_open,
       count(*) FILTER (WHERE c.status = 'waiting' AND c.first_responded_at IS NULL)::bigint AS unanswered_waiting,
       count(*) FILTER (WHERE c.status = 'closed' AND c.first_responded_at IS NULL)::bigint AS unanswered_closed
FROM conversations c
WHERE c.created_at >= $2::timestamptz AND c.created_at < $3::timestamptz
    AND c.mailbox_id = ANY($4::uuid[]) AND c.deleted_at IS NULL
    AND NOT EXISTS (SELECT 1 FROM conversation_events o WHERE o.conversation_id = c.id AND o.type = 'created' AND o.data ->> 'reason' IN ('outbound', 'campaign'))
    AND ($5::uuid IS NULL OR c.assignee_team_id = $5)
    AND ($6::uuid IS NULL OR c.assignee_user_id = $6)
    AND ($7::uuid IS NULL OR EXISTS (SELECT 1 FROM conversation_labels f WHERE f.conversation_id = c.id AND f.label_id = $7))
GROUP BY day
`

type ReportLifecycleParams struct {
	Tz         string
	RangeFrom  pgtype.Timestamptz
	RangeTo    pgtype.Timestamptz
	MailboxIds []pgtype.UUID
	TeamID     pgtype.UUID
	AgentID    pgtype.UUID
	LabelID    pgtype.UUID
}

type ReportLifecycleRow struct {
	Day               pgtype.Date
	Spam              int64
	AnsweredOpen      int64
	AnsweredWaiting   int64
	AnsweredClosed    int64
	UnansweredOpen    int64
	UnansweredWaiting int64
	UnansweredClosed  int64
}

// The conversations created in the range (the same cohort as 'new', plus spam), per local day,
// by whether we replied and by the status they have now. The Overzicht chart and flow diagram
// read these. Deleted conversations and those that began as an outbound message or a campaign
// are left out.
func (q *Queries) ReportLifecycle(ctx context.Context, arg ReportLifecycleParams) ([]ReportLifecycleRow, error) {
	rows, err := q.db.Query(ctx, reportLifecycle,
		arg.Tz,
		arg.RangeFrom,
		arg.RangeTo,
		arg.MailboxIds,
		arg.TeamID,
		arg.AgentID,
		arg.LabelID,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ReportLifecycleRow{}
	for rows.Next() {
		var i ReportLifecycleRow
		if err := rows.Scan(
			&i.Day,
			&i.Spam,
			&i.AnsweredOpen,
			&i.AnsweredWaiting,
			&i.AnsweredClosed,
			&i.UnansweredOpen,
			&i.UnansweredWaiting,
			&i.UnansweredClosed,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const reportLive = `-- name: ReportLive :one
SELECT
    count(*) FILTER (WHERE c.status = 'open' AND (c.snoozed_until IS NULL OR c.snoozed_until <= now()))::bigint AS open,
    count(*) FILTER (WHERE c.status = 'open' AND (c.snoozed_until IS NULL OR c.snoozed_until <= now()) AND c.assignee_user_id IS NULL)::bigint AS unassigned,
    count(*) FILTER (WHERE c.status = 'waiting')::bigint AS waiting,
    count(*) FILTER (WHERE c.sla_state = 'at_risk')::bigint AS sla_at_risk,
    count(*) FILTER (WHERE c.sla_state = 'breached')::bigint AS sla_breached
FROM conversations c
WHERE c.mailbox_id = ANY($1::uuid[]) AND c.status IN ('open', 'waiting') AND c.deleted_at IS NULL
    AND ($2::uuid IS NULL OR c.assignee_team_id = $2)
    AND ($3::uuid IS NULL OR c.assignee_user_id = $3)
    AND ($4::uuid IS NULL OR EXISTS (SELECT 1 FROM conversation_labels f WHERE f.conversation_id = c.id AND f.label_id = $4))
`

type ReportLiveParams struct {
	MailboxIds []pgtype.UUID
	TeamID     pgtype.UUID
	AgentID    pgtype.UUID
	LabelID    pgtype.UUID
}

type ReportLiveRow struct {
	Open        int64
	Unassigned  int64
	Waiting     int64
	SlaAtRisk   int64
	SlaBreached int64
}

// The state right now. Open excludes snoozed conversations, like the inbox does; at risk and
// breached count open and waiting conversations whose SLA sweep has not finalized them.
func (q *Queries) ReportLive(ctx context.Context, arg ReportLiveParams) (ReportLiveRow, error) {
	row := q.db.QueryRow(ctx, reportLive,
		arg.MailboxIds,
		arg.TeamID,
		arg.AgentID,
		arg.LabelID,
	)
	var i ReportLiveRow
	err := row.Scan(
		&i.Open,
		&i.Unassigned,
		&i.Waiting,
		&i.SlaAtRisk,
		&i.SlaBreached,
	)
	return i, err
}

