const reportNames = `-- name: ReportNames :many
SELECT id, name FROM (
    SELECT id, name FROM users WHERE $1::text = 'agent'
    UNION ALL SELECT id, name FROM teams WHERE $1::text = 'team'
    UNION ALL SELECT id, name FROM mailboxes WHERE $1::text = 'mailbox'
    UNION ALL SELECT id, name FROM labels WHERE $1::text = 'label'
) names
WHERE id = ANY($2::uuid[])
`

