const reportResolutionRows = `-- name: ReportResolutionRows :many
SELECT day, key, business_hours_id,
       count(*) FILTER (WHERE sla_known)::bigint AS sla_total,
       count(*) FILTER (WHERE sla_known AND sla_met)::bigint AS sla_met,
       coalesce(array_agg(wall) FILTER (WHERE business_hours_id IS NULL), '{}')::float8[] AS wall_seconds,
       coalesce(array_agg(started) FILTER (WHERE business_hours_id IS NOT NULL), '{}')::timestamptz[] AS starts,
       coalesce(array_agg(ended) FILTER (WHERE business_hours_id IS NOT NULL), '{}')::timestamptz[] AS ends
FROM (
    SELECT (CASE WHEN $1::boolean THEN (c.resolved_at AT TIME ZONE $2::text)::date ELSE $3::date END) AS day,
           (CASE $4::text WHEN 'agent' THEN c.assignee_user_id WHEN 'team' THEN c.assignee_team_id
                WHEN 'mailbox' THEN c.mailbox_id WHEN 'label' THEN cl.label_id END)::uuid AS key,
           p.business_hours_id,
           c.created_at AS started, c.resolved_at AS ended,
           extract(epoch FROM c.resolved_at - c.created_at)::float8 AS wall,
           (c.resolution_due_at IS NOT NULL)::boolean AS sla_known,
           coalesce(c.resolved_at <= c.resolution_due_at, false)::boolean AS sla_met
    FROM conversations c
    LEFT JOIN conversation_labels cl ON $4::text = 'label' AND cl.conversation_id = c.id
    LEFT JOIN sla_policies p ON p.id = c.sla_policy_id
    WHERE c.resolved_at >= $5::timestamptz AND c.resolved_at < $6::timestamptz
        AND c.status = 'closed'
        AND c.mailbox_id = ANY($7::uuid[]) AND c.deleted_at IS NULL
        AND ($8::uuid IS NULL OR c.assignee_team_id = $8)
        AND ($9::uuid IS NULL OR c.assignee_user_id = $9)
        AND ($10::uuid IS NULL OR EXISTS (SELECT 1 FROM conversation_labels f WHERE f.conversation_id = c.id AND f.label_id = $10))
) rows
GROUP BY day, key, business_hours_id
`

type ReportResolutionRowsParams struct {
	PerDay     bool
	Tz         string
	FirstDay   pgtype.Date
	Dim        string
	RangeFrom  pgtype.Timestamptz
	RangeTo    pgtype.Timestamptz
	MailboxIds []pgtype.UUID
	TeamID     pgtype.UUID
	AgentID    pgtype.UUID
	LabelID    pgtype.UUID
}

type ReportResolutionRowsRow struct {
	Day             pgtype.Date
	Key             pgtype.UUID
	BusinessHoursID pgtype.UUID
	SlaTotal        int64
	SlaMet          int64
	WallSeconds     []float64
	Starts          []pgtype.Timestamptz
	Ends            []pgtype.Timestamptz
}

// Conversations currently closed whose latest resolution falls in the range, grouped like
// ReportFirstResponseRows.
func (q *Queries) ReportResolutionRows(ctx context.Context, arg ReportResolutionRowsParams) ([]ReportResolutionRowsRow, error) {
	rows, err := q.db.Query(ctx, reportResolutionRows,
		arg.PerDay,
		arg.Tz,
		arg.FirstDay,
		arg.Dim,
		arg.RangeFrom,
		arg.RangeTo,
		arg.MailboxIds,
		arg.TeamID,
		arg.AgentID,
		arg.LabelID,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ReportResolutionRowsRow{}
	for rows.Next() {
		var i ReportResolutionRowsRow
		if err := rows.Scan(
			&i.Day,
			&i.Key,
			&i.BusinessHoursID,
			&i.SlaTotal,
			&i.SlaMet,
			&i.WallSeconds,
			&i.Starts,
			&i.Ends,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
